script:
let body = 
    {
        "name": "My new board template",
        "description": "This is a new test description for a board template",
        "accessPolicy": "PUBLIC",
        "favourite": true,
        "columnTemplates": [ 
            { 
                "name": "Lean coffee", 
                "description":"A template column description", 
                "visible": true,
                "color": "backlog-blue"
            },
            { 
                "name": "Actions", 
                "description":"A template column description", 
                "visible": false, 
                "color": "planning-pink"
            }
        ]
    };

body = JSON.stringify(body)

pm.sendRequest({
    url: pm.variables.get("base_url") + "/templates",
    method: 'POST',
    header: {
        "Content-Type": "application/json; charset=utf-8",
        "Authorization": pm.collectionVariables.get("jwt"),
    },
    body: body

}, function (err, response) {
    const res = response.json();

    pm.test("PreRequestScript – Successful POST request (createBoardTemplate)", () => {
        pm.expect(response.code).to.be.equal(201);
    });

    pm.test("PreRequestScript – Check id", () => {
        pm.expect(res.id).to.exist;
    })

    pm.collectionVariables.set("board_template_id", res.id);
});

